@ obj i warp map=CASA_INES x=7 y=10 face=UP                                          ; puerta de la casa de Ines (la de Leo)
@ obj p warp map=POSADA x=7 y=10 face=UP                                             ; puerta de la posada / cocina de Tomasa
@ obj t warp map=TIENDA x=7 y=10 face=UP                                             ; puerta de la tienda
@ obj e warp map=ENFERMERIA x=7 y=10 face=UP                                         ; puerta de la enfermeria
@ obj V sign script=cartel_varadero                                                  ; cartel del pueblo en la plaza
@ obj M sign script=cartel_bruma                                                     ; cartel junto al muro de bruma del este
@ obj f patch flag=F_BRUMA_1 mt=7                                                    ; bruma -> camino (anillo 1)
@ obj g patch flag=F_BRUMA_1 mt=8                                                    ; bruma -> camino (anillo 1)
@ obj A npc look=LOOK_ABUELA face=DOWN beh=LOOK script=vecina_rosa                   ; vecina mayor junto al jardin de Ines
@ obj C npc look=LOOK_VECINA face=DOWN beh=WANDER script=vecina_plaza                ; vecina paseando por la plaza
@ obj N npc look=LOOK_PESCADOR face=DOWN beh=LOOK script=pescador_redes              ; pescador remendando redes en la playa
@ obj B forage table=FORAGE_BAYAS                                                    ; zarzamora del jardin de Ines
@ obj s spawn table=SPAWN_PLAYA_VAR radius=3                                         ; playa oeste: Pinzarro
@ obj S spawn table=SPAWN_PLAYA_VAR radius=3                                         ; playa este: Pinzarro
@ obj w trigger script=aviso_sendero once=F_AVISO_SENDERO                            ; salida al Sendero del Cabo
@ obj u item item=ITEM_CONCHAS_50 n=1 flag=F_PICK_VAR_1                              ; junto a la barca varada oeste
@ obj v item item=ITEM_POCION n=1 flag=F_PICK_VAR_2                                  ; rincon del jardin de Ines
@ obj I trigger script=intro_muelle once=F_INTRO                                     ; primer paso en el muelle
@ obj F npc look=LOOK_PESCADOR face=DOWN beh=STILL script=pescador_muelle            ; pescador al final del muelle (encargo del machete)
@ obj c sign script=cartel_claro                                                     ; cartel viejo junto al campamento del claro
@ obj q spawn table=SPAWN_CLARO radius=3                                             ; hierba alta del claro
@ obj Q spawn table=SPAWN_CHARCA radius=3                                            ; orilla de la charca del claro (Sapoyo)
@ obj b forage table=FORAGE_BAYAS                                                    ; zarzamora del claro
@ obj o item item=ITEM_FAROLILLO_FINO n=1 flag=F_PICK_CLARO_1                        ; premio del claro
@ obj r trigger script=claro_entrada once=F_CLARO_VISTO                              ; primer paso dentro del claro (tras las zarzas)
@ obj d spawn table=SPAWN_SENDERO radius=3                                           ; hierba alta norte del sendero
@ obj D spawn table=SPAWN_SENDERO radius=3                                           ; hierba alta central del sendero
@ obj y forage table=FORAGE_BAYAS                                                    ; zarzamora junto al campamento del sendero
@ obj h sign script=cartel_sendero                                                   ; cartel antes del cabo
@ obj j item item=ITEM_POCION n=1 flag=F_PICK_SEN_1                                  ; objeto escondido en la hierba
@ obj m item item=ITEM_MADERA n=1 flag=F_PICK_SEN_2                                  ; lena junto al campamento (tutorial de acampar)
@ obj L warp map=FARO_PB x=7 y=10 face=UP                                            ; puerta del faro
@ obj k sign script=cartel_faro                                                      ; placa del faro junto a la puerta
@ obj x spawn table=SPAWN_CABO radius=3                                              ; rocas y hierba del cabo
@ obj X spawn table=SPAWN_CABO radius=3                                              ; playa de rocas bajo el acantilado
@ obj z item item=ITEM_POCION n=1 flag=F_PICK_CABO_1                                 ; objeto en la playa de rocas
@ obj Z item item=ITEM_CEBO_DULCE n=1 flag=F_PICK_CABO_2                             ; cebo escondido en la hierba del cabo
@ obj K trigger script=faro_cerrado once=F_FARO_ABIERTO                              ; delante de la puerta del faro: cerrada hasta F_FARO_ABIERTO
@ obj R forage table=FORAGE_RAMAS                                                    ; rama seca junto al campamento del sendero
@ obj G forage table=FORAGE_RAMAS                                                    ; rama seca en el claro
